import numpy as np
from cytools_agent.tools import polytope
ids = polytope.fetch_polytopes(limit=1, h11=2)
ks = ids[0]
p = polytope.get_polytope(ks)
def find_rigids(p):
    return sorted([int_point for ft in range(3) for face in p.faces(ft)
        for int_point in face.interior_points(as_indices=True)
        if len(face.dual_face().interior_points()) == 0])
print(len(find_rigids(p)))

